try:
    print('>>> x = (1, 2)')
    print('>>> y = range(0)')
    print('>>> x <<= y')
    print('>>> x')
    x = (1, 2)
    y = range(0)
    x <<= y
    print(x)
except Exception as e:
    print(type(e), ':', e)
print()
